#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s: %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# ──────────────────────────────────────────────────────────────────────────
# TrackIn: primer despliegue en el servidor de producción (`PROD-09`).
#
# Se corre en el servidor Linux, desde la raíz del repositorio clonado:
#
#   bash scripts/asistente_produccion.sh
#
# Sigue docs/deployment.md §7 y escribe .env.produccion. Se puede cortar con
# Ctrl-C y volver a correr: recuerda lo guardado y salta lo que ya está hecho.
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE=".env.produccion"
DC=(docker compose --env-file "$ENV_FILE")

_aleatorio() { # _aleatorio N: N caracteres aleatorios, sin símbolos raros
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -base64 96 | tr -d '\n/+=' | cut -c1-"$1"
  else
    python3 -c "import secrets,sys; print(secrets.token_urlsafe(96)[:int(sys.argv[1])])" "$1"
  fi
}

_version_minima() { # _version_minima ACTUAL MINIMA: éxito si ACTUAL >= MINIMA
  [[ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | head -n1)" == "$2" ]]
}

_esperar_salud() { # espera hasta 2 minutos a que /health diga "ok"
  local puerto="${TRACKIN_PUERTO:-8080}" i
  for i in $(seq 1 24); do
    if curl -fsS "http://localhost:${puerto}/health" 2>/dev/null | grep -q '"status":"ok"'; then
      return 0
    fi
    sleep 5
  done
  return 1
}

_responde() { # _responde URL: el worker llega a URL (cualquier respuesta HTTP sirve)
  "${DC[@]}" exec -T worker python - "$1" >/dev/null 2>&1 <<'PY'
import sys, urllib.request, urllib.error
try:
    urllib.request.urlopen(sys.argv[1], timeout=10)
except urllib.error.HTTPError:
    pass
PY
}

run_wizard() {

TOTAL_STAGES=12

banner "TrackIn: primer despliegue en producción"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Requisitos del servidor"
say "Se revisa que el servidor tenga lo que pide docs/deployment.md §6."
if [[ ! -f docker-compose.yml || ! -f .env.produccion.example ]]; then
  warn "Esto no es la raíz del repositorio de TrackIn. Entrar a la carpeta clonada y volver a correr."
  exit 1
fi
for c in docker git curl; do
  command -v "$c" >/dev/null 2>&1 || { warn "Falta $c. Pedirlo a TI antes de seguir."; exit 1; }
done
if ! docker info >/dev/null 2>&1; then
  warn "Docker no responde para este usuario: ¿está corriendo, y el usuario está en el grupo docker?"
  exit 1
fi
v_docker=$(docker version --format '{{.Server.Version}}')
v_compose=$(docker compose version --short 2>/dev/null | sed 's/^v//')
say "Docker $v_docker, compose $v_compose"
_version_minima "$v_docker" "24.0" || { warn "Hace falta Docker 24 o superior."; exit 1; }
_version_minima "$v_compose" "2.24" || { warn "Hace falta el plugin compose 2.24 o superior."; exit 1; }
pause "Todo en orden. Enter para seguir."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Versión a desplegar"
git fetch --tags --quiet || warn "No se pudieron traer las etiquetas de GitHub; se usan las locales."
actual=$(git describe --tags --exact-match 2>/dev/null || echo "sin etiqueta ($(git rev-parse --short HEAD))")
ultima=$(git tag --list 'v*' --sort=-v:refname | head -n1)
say "Ahora: $actual"
say "Última etiqueta: ${ultima:-ninguna}"
if [[ -z "$ultima" ]]; then
  warn "Todavía no hay etiquetas vX.Y.Z (PROD-06): se despliega lo que está en la carpeta."
elif [[ "$actual" != "$ultima" ]] && confirm "¿Cambiar a $ultima?"; then
  git checkout --quiet "$ultima" && say "En $ultima."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Secretos de la base y de las sesiones"
say "Se generan aquí y van directo a $ENV_FILE, sin mostrarse."
note "Si ya existen, se conservan: cambiar SECRET_KEY cierra todas las sesiones,"
note "y cambiar POSTGRES_PASSWORD con la base ya creada la deja inaccesible."
if [[ -z "$(_existing POSTGRES_PASSWORD || true)" ]]; then
  write_env POSTGRES_PASSWORD "$(_aleatorio 40)"
else
  say "POSTGRES_PASSWORD ya existe: se conserva."
fi
if [[ -z "$(_existing SECRET_KEY || true)" ]]; then
  write_env SECRET_KEY "$(_aleatorio 64)"
else
  say "SECRET_KEY ya existe: se conserva."
fi
write_env POSTGRES_USER "$(_existing POSTGRES_USER || echo trackin)"
write_env POSTGRES_DB "$(_existing POSTGRES_DB || echo trackin)"
write_env ENVIRONMENT production
write_env DEBUG false
write_env VITE_API_URL ""
[[ -n "$(_existing SAP_INTEGRACION_CLAVE || true)" ]] || write_env SAP_INTEGRACION_CLAVE ""
note "SAP_INTEGRACION_CLAVE queda vacía: la escucha de SAP va apagada (D14)."
note "Entregar a TI una copia de $ENV_FILE para su custodia (PROD-14)."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Nombre y puerto"
say "El nombre interno que TI dio de alta en el DNS (D7) y el puerto de este"
say "servidor al que apunta el proxy con HTTPS."
ask DOMINIO "Nombre, sin https (por ejemplo trackin.gutis.com):"
DOMINIO="${DOMINIO#https://}"
write_env BACKEND_CORS_ORIGINS "https://$DOMINIO"
ask TRACKIN_PUERTO "Puerto del panel en este servidor (8080 si no se acordó otro):"
write_env TRACKIN_PUERTO "${TRACKIN_PUERTO:-8080}"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Token de la API de ShipsGo"
say "Es el que da de alta y consulta los embarques. Solo producción lo tiene (ADR 0003)."
step "Entrar a la cuenta de ShipsGo de Gutis → Settings → API."
step "Copiar el token de la API (no el del mapa embebido)."
note "Vacío: TrackIn funciona, pero no rastrea."
ask_secret SHIPSGO_API_TOKEN "Pegar el token de la API (no se ve al escribir):"
write_env SHIPSGO_API_TOKEN "$SHIPSGO_API_TOKEN"
warn "Después de la salida, borrar este token de los equipos de desarrollo (PROD-12)."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Mapa embebido de ShipsGo (opcional)"
say "El mapa en vivo del detalle usa otro token, que queda dentro del panel."
step "En la cuenta de ShipsGo, abrir la configuración de ShipsGo Embed."
step "Agregar https://$DOMINIO a «Allowed HTTP Origins»."
step "Copiar el token del mapa embebido."
note "Vacío: el detalle usa el mapa propio de TrackIn."
ask VITE_SHIPSGO_EMBED_TOKEN "Pegar el token del mapa embebido (Enter para dejarlo vacío):" \
  || VITE_SHIPSGO_EMBED_TOKEN=""
write_env VITE_SHIPSGO_EMBED_TOKEN "$VITE_SHIPSGO_EMBED_TOKEN"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Construir las imágenes"
say "Construye la API, el worker y el panel. La primera vez tarda varios minutos."
if ! "${DC[@]}" config --quiet; then
  warn "docker compose rechaza la configuración: revisar $ENV_FILE."
  exit 1
fi
if confirm "¿Construir ahora?"; then
  "${DC[@]}" build
else
  SKIPPED+=("Construir las imágenes: ${DC[*]} build")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Base de datos y migraciones"
say "Levanta PostgreSQL y crea las tablas y los maestros. Va antes de la API y el worker."
"${DC[@]}" up -d postgres
say "Esperando a que la base acepte conexiones..."
for _ in $(seq 1 30); do
  "${DC[@]}" exec -T postgres pg_isready -q && break
  sleep 2
done
"${DC[@]}" run --rm backend alembic upgrade head
say "Migración actual:"
"${DC[@]}" run --rm backend alembic current 2>/dev/null | tail -n1
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Primer Administrador"
say "La cuenta con la que se entra la primera vez. Las demás se crean desde el panel."
ask ADMIN_USUARIO "Usuario del Administrador:"
ask ADMIN_NOMBRE "Nombre completo:"
note "Ahora se pide la contraseña dos veces, sin mostrarla (mínimo 10 caracteres)."
if ! "${DC[@]}" run --rm backend python scripts/crear_usuario.py "$ADMIN_USUARIO" "$ADMIN_NOMBRE" ADMINISTRADOR; then
  warn "No se creó. Si dice que ya existe, se puede seguir."
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Levantar TrackIn y verificar /health"
"${DC[@]}" up -d
say "Esperando a que la API responda..."
if _esperar_salud; then
  say "/health responde:"
  curl -fsS "http://localhost:${TRACKIN_PUERTO:-8080}/health"
  printf '\n'
else
  warn "/health no respondió en 2 minutos. Ver: ${DC[*]} logs backend"
  SKIPPED+=("/health no respondió tras levantar TrackIn")
fi
"${DC[@]}" ps
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Salida a internet desde el servidor"
say "El worker tiene que llegar a ShipsGo y a TICA (docs/deployment.md §3)."
for url in https://api.shipsgo.com https://ticaconsultas.hacienda.go.cr; do
  if _responde "$url"; then
    say "✓ $url"
  else
    warn "✗ $url no responde: pedir a TI que lo deje pasar (PROD-17)."
    SKIPPED+=("Salida a $url")
  fi
done
note "Los mosaicos del mapa y embed.shipsgo.com los pide el navegador de cada usuario:"
note "se verifican desde un equipo de planta (PROD-17)."
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Respaldo de prueba y HTTPS"
if ENV_FILE="$ENV_FILE" bash scripts/respaldar.sh primer-despliegue; then
  say "✓ Respaldo de prueba en respaldos/ (scripts/respaldar.sh, PROD-07)"
  note "La restauración se prueba en el ensayo general (PROD-18, PROD-20)."
  note "Falta programarlo todos los días: docs/deployment.md §8."
else
  warn "El respaldo falló o quedó vacío."
  SKIPPED+=("Respaldo de prueba")
fi
say ""
say "Falta lo que hace TI: que el proxy con HTTPS apunte a este servidor, puerto ${TRACKIN_PUERTO:-8080}."
step "Desde un equipo de la red, abrir https://$DOMINIO"
step "Comprobar el candado sin advertencias y entrar con $ADMIN_USUARIO."
if ! confirm "¿Se ve el inicio de sesión por HTTPS, sin advertencias?"; then
  SKIPPED+=("HTTPS en https://$DOMINIO (PROD-16)")
fi

finish
say "Siguiente: el ensayo general (PROD-20) y el checklist de docs/deployment.md §11."
printf '\n'
}

run_wizard "$@"; exit
